declarations.type:
∀ {requirement : SearchRouteCost.RouteRequirement} {budget : SearchRouteDAG.GraphRouteBudget}
  {snapshot : SearchRouteEvidenceGraphRouter.EvidenceGraphSnapshot}
  {candidate : SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate},
  SearchRouteEvidenceGraphRouter.CertifiedFeasible requirement budget snapshot candidate →
    SearchRouteEvidenceGraphRouter.RuntimeReady candidate

∀ {requirement : SearchRouteCost.RouteRequirement} {budget : SearchRouteDAG.GraphRouteBudget}
  {snapshot : SearchRouteEvidenceGraphRouter.EvidenceGraphSnapshot}
  {candidate : SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate},
  candidate.evidenceRootDigest ≠ snapshot.rootDigest →
    ¬SearchRouteEvidenceGraphRouter.CertifiedFeasible requirement budget snapshot candidate

∀ {requirement : SearchRouteCost.RouteRequirement} {budget : SearchRouteDAG.GraphRouteBudget}
  {snapshot : SearchRouteEvidenceGraphRouter.EvidenceGraphSnapshot}
  {candidate : SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate},
  candidate.projectionCompatible = false →
    ¬SearchRouteEvidenceGraphRouter.CertifiedFeasible requirement budget snapshot candidate

∀ {requirement : SearchRouteCost.RouteRequirement} {budget : SearchRouteDAG.GraphRouteBudget}
  {snapshot : SearchRouteEvidenceGraphRouter.EvidenceGraphSnapshot}
  {catalog : List SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate}
  (selection : SearchRouteEvidenceGraphRouter.CertifiedSelection requirement budget snapshot catalog)
  (candidate : SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate),
  candidate ∈ catalog →
    SearchRouteEvidenceGraphRouter.CertifiedFeasible requirement budget snapshot candidate →
      SearchRouteDAG.graphLexNoWorse selection.selected.graphCandidate candidate.graphCandidate

∀ {requirement : SearchRouteCost.RouteRequirement} {budget : SearchRouteDAG.GraphRouteBudget}
  {snapshot : SearchRouteEvidenceGraphRouter.EvidenceGraphSnapshot}
  {candidateUniverse catalog : List SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate}
  (selection : SearchRouteEvidenceGraphRouter.CertifiedSelection requirement budget snapshot catalog),
  SearchRouteEvidenceGraphRouter.CertifiedCatalogComplete requirement budget snapshot candidateUniverse catalog →
    ∀ (candidate : SearchRouteEvidenceGraphRouter.ExecutableGraphCandidate),
      candidate ∈ candidateUniverse →
        SearchRouteEvidenceGraphRouter.CertifiedFeasible requirement budget snapshot candidate →
          SearchRouteDAG.graphLexNoWorse selection.selected.graphCandidate candidate.graphCandidate
